import com.wolinski.shop.customers.api.CustomerFacade;
import com.wolinski.shop.notifications.api.Notifier;
import com.wolinski.shop.orders.api.OrderCancelled;
import org.springframework.stereotype.Component;
import org.springframework.transaction.event.TransactionPhase;
import org.springframework.transaction.event.TransactionalEventListener;

/** Tells the customer about a cancellation, but only once the cancellation has actually committed. */
@Component
public class CancellationNotifications {

    private final Notifier notifier;
    private final CustomerFacade customers;

    public CancellationNotifications(Notifier notifier, CustomerFacade customers) {
        this.notifier = notifier;
        this.customers = customers;
    }

    @TransactionalEventListener(phase = TransactionPhase.AFTER_COMMIT)
    void on(OrderCancelled cancelled) {
        String address = customers.emailOf(cancelled.customerId());
        if (address == null) {
            return;
        }
        notifier.send(address,
                "Order " + cancelled.orderId() + " cancelled",
                "Your order " + cancelled.orderId() + " has been cancelled.");
    }
}
}

