import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import com.wolinski.shop.customers.api.CustomerFacade;
import com.wolinski.shop.money.Money;
import com.wolinski.shop.notifications.api.MailTransport;
import com.wolinski.shop.orders.api.OrderFacade;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import org.junit.jupiter.api.Test;
import org.springframework.context.annotation.AnnotationConfigApplicationContext;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Primary;

class CancellationMailTest {

    static class RecordingConfig {
        final List<String[]> sent = new ArrayList<>();

        @Bean
        @Primary
        MailTransport recordingTransport() {
            return (address, subject, body) -> sent.add(new String[] {address, subject, body});
        }
    }

    @Test
    void cancellingAnOrderMailsTheCustomerOnce() {
        RecordingConfig recording = new RecordingConfig();
        try (var shop = new AnnotationConfigApplicationContext()) {
            shop.registerBean(RecordingConfig.class, () -> recording);
            shop.register(ShopConfig.class);
            shop.refresh();

            OrderFacade orders = shop.getBean(OrderFacade.class);
            CustomerFacade customers = shop.getBean(CustomerFacade.class);
            customers.register("c-1", "ann@example.com");

            String id = orders.place("c-1", Money.pln(1000), Instant.parse("2026-10-01T10:00:00Z"));
            assertEquals(0, recording.sent.size());

            orders.cancel(id);
            orders.cancel(id);

            assertEquals(1, recording.sent.size());
            String[] mail = recording.sent.get(0);
            assertEquals("ann@example.com", mail[0]);
            assertTrue(mail[1].contains(id), "subject should contain the order id");
        }
    }

    @Test
    void aFailedCancellationSendsNothing() {
        RecordingConfig recording = new RecordingConfig();
        try (var shop = new AnnotationConfigApplicationContext()) {
            shop.registerBean(RecordingConfig.class, () -> recording);
            shop.register(ShopConfig.class);
            shop.refresh();

            OrderFacade orders = shop.getBean(OrderFacade.class);
            shop.getBean(CustomerFacade.class).register("c-1", "ann@example.com");
            String id = orders.place("c-1", Money.pln(1000), Instant.parse("2026-10-01T10:00:00Z"));

            org.junit.jupiter.api.Assertions.assertThrows(RuntimeException.class, () -> orders.cancel("missing"));
            assertEquals(0, recording.sent.size());
            assertEquals("PLACED", orders.summary(id).status());
        }
    }
}
}

